{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In humans, lycopene—a large lipophilic isoprenoid with poor aqueous solubility—showed only ~2.6% systemic availability from a 38-mg capsule dose, supporting low oral bioavailability for the similarly large, highly lipophilic isoprenoid quinone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In humans, all-trans lycopene bioavailability was 12.2 ± 2.1%, below the 20% threshold, reinforcing that large crystalline isoprenoids are incompletely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Phytoene showed absolute bioavailability of 58.5 ± 18.9% in humans, which would support high F, but this is less transferable because phytoene is a smaller, nonpolar C40 hydrocarbon without the polar quinone head and larger molecular size of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a large, highly lipophilic ubiquinone-like isoprenoid with very low aqueous solubility. Human lycopene data, a closer model for a poorly soluble crystalline isoprenoid, consistently show systemic availability below 20%, while the higher phytoene value is less transferable due to its smaller nonpolar hydrocarbon structure. The weight of evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for the query molecule itself.",
    "Lycopene records are mostly systemic availability estimates rather than true absolute bioavailability.",
    "Phytoene high-bioavailability evidence has limited structural transferability to the polar quinone-containing, higher-molecular-weight query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

